module protocol::adl_admin;

use std::option::{none, some};
use std::type_name::TypeName;

use sui::clock::Clock;
use sui::event::emit;

use protocol::error;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;
use protocol::adl::DeleverageParams;
use math::float;
use protocol::adl::new_auto_deleverage_params;

const BPS_DENOMINATOR: u64 = 10000;
const LARGE_DENOMINATOR: u64 = 1000000000000000000;
const MAX_DELAY_SECONDS: u64 = 259200; // 3 days

public struct NewADLSetEvent has copy, drop {
    market: TypeName,
    coin: TypeName,

    is_borrow: bool,
    emode_group_id: Option<u8>,

    params: DeleverageParams,
    activation_timestamp: u64,

    time: u64,
    operator: address,
}

public struct ADLCancelEvent has copy, drop {
    market: TypeName,
    coin: TypeName,

    is_borrow: bool,
    emode_group_id: Option<u8>,

    time: u64,
    operator: address,
}

public fun new_adl_params<MarketType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &Market<MarketType>,

    target_amount: u64,

    liquidation_factor_base_bps: u64,
    liquidation_factor_hourly_drop_large: u64,

    liquidation_incentive_base_bps: u64,
    liquidation_incentive_daily_penalty_large: u64,

    close_factor_bps: u64,
): DeleverageParams {
    assert!(0 < liquidation_factor_base_bps && liquidation_factor_base_bps <= BPS_DENOMINATOR, error::invalid_params_error());
    assert!(0 < close_factor_bps && close_factor_bps <= BPS_DENOMINATOR, error::invalid_params_error());

    check_market<MarketType>(self, market);

    let liquidation_factor_base = float::from_quotient(liquidation_factor_base_bps, BPS_DENOMINATOR);
    let liquidation_factor_hourly_drop = float::from_quotient(liquidation_factor_hourly_drop_large, LARGE_DENOMINATOR);

    let liquidation_incentive_base = float::from_quotient(liquidation_incentive_base_bps, BPS_DENOMINATOR);
    let liquidation_incentive_daily_penalty = float::from_quotient(liquidation_incentive_daily_penalty_large, LARGE_DENOMINATOR);

    let close_factor = float::from_quotient(close_factor_bps, BPS_DENOMINATOR);

    new_auto_deleverage_params(
        target_amount, 
        liquidation_factor_base, 
        liquidation_factor_hourly_drop, 
        liquidation_incentive_base, 
        liquidation_incentive_daily_penalty, 
        close_factor
    )
}

public fun enable_collateral_adl<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,

    params: DeleverageParams,
    seconds_from_now: u64,

    clock: &Clock,
    ctx: &TxContext,
) {
    assert!(seconds_from_now <= MAX_DELAY_SECONDS, error::invalid_params_error());

    check_market<MarketType>(self, market);

    let registry = market.adl_registry_mut();

    let now = clock.timestamp_ms() / 1000;
    let activation_timestamp = now + seconds_from_now;

    registry.enable_collateral_deleverage<CoinType>(params, activation_timestamp);

    emit(NewADLSetEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        coin: std::type_name::with_defining_ids<CoinType>(),

        is_borrow: false,
        emode_group_id: none(),

        params: params,
        activation_timestamp,

        time: now,
        operator: ctx.sender(),
    });
}

public fun cancel_collateral_adl<MarketType, CoinType>(
    _: &AdminCap,

    self: &ProtocolApp,
    market: &mut Market<MarketType>,

    clock: &Clock,
    ctx: &TxContext,
) {
    check_market<MarketType>(self, market);

    let registry = market.adl_registry_mut();
    let market_type = std::type_name::with_defining_ids<MarketType>();

    registry.stop_collateral_deleverage<CoinType>(market_type);

    emit(ADLCancelEvent {
        market: market_type,
        coin: std::type_name::with_defining_ids<CoinType>(),
        is_borrow: false,
        emode_group_id: none(),
        time: clock.timestamp_ms(),
        operator: ctx.sender(),
    });
}

public fun enable_debt_adl<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,

    emode_group_id: u8,
    params: DeleverageParams,
    seconds_from_now: u64,

    clock: &Clock,
    ctx: &mut TxContext,
) {
    assert!(seconds_from_now <= MAX_DELAY_SECONDS, error::invalid_params_error());

    check_market<MarketType>(self, market);

    let registry = market.adl_registry_mut();

    let now = clock.timestamp_ms() / 1000;
    let activation_timestamp = now + seconds_from_now;

    registry.enable_debt_deleverage<CoinType>(emode_group_id, params, activation_timestamp, ctx);

    emit(NewADLSetEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        coin: std::type_name::with_defining_ids<CoinType>(),

        is_borrow: true,
        emode_group_id: some(emode_group_id),

        params: params,
        activation_timestamp,

        time: now,
        operator: ctx.sender(),
    });
}

public fun cancel_debt_adl<MarketType, CoinType>(
    _: &AdminCap,

    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    emode_group_id: u8,

    clock: &Clock,
    ctx: &mut TxContext,
) {
    check_market<MarketType>(self, market);

    let registry = market.adl_registry_mut();
    let market_type = std::type_name::with_defining_ids<MarketType>();

    registry.stop_borrow_deleverage<CoinType>(market_type, emode_group_id);

    emit(ADLCancelEvent {
        market: market_type,
        coin: std::type_name::with_defining_ids<CoinType>(),

        is_borrow: true,
        emode_group_id: some(emode_group_id),

        time: clock.timestamp_ms() / 1000,
        operator: ctx.sender(),
    });
}

fun check_market<MarketType>(
    self: &ProtocolApp,
    market: &Market<MarketType>,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();
}

/// @title Module for handling the liquidation request
/// @notice adopts soft liquidation. Liquidation amount should be no bigger than the amount that would drecrease the risk level of obligation to 1.
module protocol::liquidate;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::Coin;
use sui::event::emit;
use x_oracle::user_oracle::get_price;
use x_oracle::x_oracle::XOracle;
use math::float::Decimal;
use protocol::liquidity_miner::{get_borrow_reward_type, get_deposit_reward_type};
use protocol::app::{ProtocolApp, PackageCallerCap};

public enum LiquidationType has copy, drop{
    NormalLiquidation,
    ADLBorrow,
    ADLCollateral,
}

public struct LiquidateEvent has copy, drop {
    liquidator: address,
    liquidation_type: LiquidationType,

    market: TypeName,
    obligation: ID,


    collateral_price: Decimal,
    debt_price: Decimal,

    collateral_type: TypeName,
    seized_ctoken_amount: u64,
    seized_collateral_amount: u64,
    ctokens_remaining: u64,

    debt_type: TypeName,
    total_borrow_remaining: Decimal,
    borrow_index: Decimal,
    repay_amount: u64,
    refund_amount: u64,

    timestamp: u64,
}

fun pre_liquidation_check<MarketType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,
    market: &Market<MarketType>,
    permission: u8,
) {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    app.ensure_has_permission(object::id(cap), permission);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());
}

fun post_liquidation<MarketType, DebtType, CollateralType>(
    now: u64,
    repay_amount: u64,
    refund_amount: u64,
    liquidation_type: LiquidationType,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    collateral_amount: u64,
    ctoken_amount: u64,

    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &TxContext,
) {
    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let obligation = market.borrow_obligation(obligation_id);
    let oracle = market.emode_registry().borrow_emode_group(obligation.emode_group()).get_oracle_base_token();

    let total_ctoken_amount = obligation.ctoken_amount_by_coin(collateral_type);
    let (total_borrow, borrow_index) = if (obligation.has_debt(debt_type)) {
        let debt = obligation.debt(debt_type);
        (debt.unsafe_debt_amount(), *debt.borrow_index())
    }  else {
        (math::float::zero(), math::float::one())
    };

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, DebtType>(
        get_borrow_reward_type(),
        obligation_id,
        total_borrow.floor(),
        clock
    );
    miner.update_obligation_reward_manager<MarketType, CollateralType>(
        get_deposit_reward_type(),
        obligation_id,
        total_ctoken_amount,
        clock
    );

    emit(LiquidateEvent {
        liquidator: ctx.sender(),
        liquidation_type,

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_id,

        debt_type,
        collateral_type,

        collateral_price: get_price(x_oracle, type_name::with_defining_ids<CollateralType>(), oracle, clock),
        debt_price: get_price(x_oracle, type_name::with_defining_ids<DebtType>(), oracle, clock),

        seized_ctoken_amount: ctoken_amount,
        seized_collateral_amount: collateral_amount,
        ctokens_remaining: total_ctoken_amount,

        total_borrow_remaining: total_borrow,
        borrow_index,
        repay_amount,
        refund_amount,

        timestamp: now,
    });
}

#[allow(lint(self_transfer))]
public fun liquidate<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let (collateral_balance, refund) = liquidate_as_coin<MarketType, DebtType, CollateralType>(
        app,
        cap,
        obligation_id, 
        market, 
        available_repay_coin, 
        coin_decimals_registry, 
        x_oracle, 
        clock, 
        ctx
    );
    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

public fun liquidate_as_coin<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::liquidation());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_liquidation<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount,
        refund.value(),
        LiquidationType::NormalLiquidation, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    (collateral_balance, refund)
}

#[allow(lint(self_transfer))]
public fun liquidate_adl_borrow<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::adl());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_debt_auto_deleverage<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount,
        refund.value(),
        LiquidationType::ADLBorrow, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

#[allow(lint(self_transfer))]
public fun liquidate_adl_deposit<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::adl());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_collateral_auto_deleverage<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount, 
        refund.value(),
        LiquidationType::ADLCollateral, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

