public(package) fun handle_liquidation<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let MarketConfiguration { close_factor, close_factor_bypass_min_value } = *self.market_config();

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    let emode_group_id = obligation.emode_group();
    let collateral_name = type_name::with_defining_ids<CollateralType>();

    let emode_group = self.emode_group_registry.borrow_emode_group_mut(emode_group_id);
    let collateral_setting = emode_group.borrow_emode(collateral_name).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let asset = self.assets.load_mut_by_type(collateral_name);
    assert!(!asset.liquidation_paused(), error::liquidation_paused_for_asset());

    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::none(),
        liquidation_incentive: collateral_setting.liquidation_incentive(),
        liquidation_revenue_factor: self.assets.load_by_type(type_name::with_defining_ids<CollateralType>()).asset_config().liquidation_fee_rate(),
        close_factor,
        close_factor_bypass_min_value,
    };

    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    )
}

public(package) fun handle_debt_auto_deleverage<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;

    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    let emode_group_id = obligation.emode_group();
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());

    let collateral_setting = emode_group.borrow_emode(collateral_type).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let max_liquidation_incentive = collateral_setting.liquidation_incentive();


    let adl_registry = dynamic_field::borrow<ADLRegistryKey, AutoDeleverageRegistry>(&self.id, ADLRegistryKey {});
    let timelock = *adl_registry.get_borrow_deleverage(debt_type, emode_group_id);

    let asset = self.assets.load_mut_by_type(debt_type);
    accrue_interest<MarketType>(debt_type, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let total_debt = (*self.reserves.load_by_type(debt_type).debt()).floor();
    let debt_params = timelock.inner();
    debt_params.ensure_limit_breached(total_debt);


    let activation_time = timelock.get_secs_since_activation(clock);
    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::some(debt_params.liquidation_ltv(activation_time)),
        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
        liquidation_incentive: debt_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
        liquidation_revenue_factor: float::zero(),
        close_factor: debt_params.close_factor(),
        close_factor_bypass_min_value,
    };



    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    )
}

public(package) fun handle_collateral_auto_deleverage<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;

    let collateral = type_name::with_defining_ids<CollateralType>();

    // load the time locked adl params
    let adl_registry = self.adl_registry<MarketType>();
    let timelock = *adl_registry.get_collateral_deleverage(collateral);

    // refresh obligation
    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    // obtain the emode group
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());

    // make sure the Collateral Type is indeed a collateral, otherwise revert
    let collateral_setting = emode_group.borrow_emode(collateral).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let max_liquidation_incentive = collateral_setting.liquidation_incentive();

    // force interest update for the collateral asset
    let asset = self.assets.load_mut_by_type(collateral);
    accrue_interest<MarketType>(collateral, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let total_deposit = self.reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().floor();
    let collateral_params = timelock.inner();
    collateral_params.ensure_limit_breached(total_deposit);
    let activation_time = timelock.get_secs_since_activation(clock);

    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::some(collateral_params.liquidation_ltv(activation_time)),
        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
        liquidation_incentive: collateral_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
        liquidation_revenue_factor: float::zero(),
        close_factor: collateral_params.close_factor(),
        close_factor_bypass_min_value,
    };

    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,

fun liquidation_inner<MarketType, DebtType, CollateralType>(
    id: &mut UID,

    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    emode_group: &mut EModeGroup,

    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,

    obligation: &mut Obligation<MarketType>,
    liquidation_params: &LiquidationParams,

    mut available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    now: u64,

    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    assert!(available_repay_coin.value() != 0, error::liquidation_zero_repay());

    let debt_name = type_name::with_defining_ids<DebtType>();
    let collateral_name = type_name::with_defining_ids<CollateralType>();

    let obligation_old_borrow_amount = obligation.debt(debt_name).unsafe_debt_amount();

    // update all assets interest in the obligation
    refresh_obligation_assets_interest(assets, emode_group, reserves, obligation, now);

    ensure_liquidate_borrow_allowed<MarketType, DebtType>(
        liquidation_params,
        obligation,
        emode_group,
        reserves,
        coin_decimals_registry,
        available_repay_coin.value(),
        x_oracle,
        clock,
    );

    // calculate how much collateral can be seized first
    let obligation_latest_borrow_amount = obligation.debt(debt_name)
        .unsafe_debt_amount()
        // repay a bit more
        .ceil();
    let mut refund_coins = if (obligation_latest_borrow_amount < available_repay_coin.value()) {
        let refund_amount = available_repay_coin.value() - obligation_latest_borrow_amount;
        available_repay_coin.split(refund_amount, ctx)
    } else {
        sui::coin::zero(ctx)
    };

    // NOTE: disable rate limit

    let collateral_reserve = reserves.load_mut_by_type(type_name::with_defining_ids<CollateralType>());
    let exchange_rate = collateral_reserve.exchange_rate<MarketType>(); 

    let mut seized_ctokens = liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
        exchange_rate,
        liquidation_params.liquidation_incentive,
        available_repay_coin.value(),
        emode_group.get_oracle_base_token(),
        x_oracle,
        coin_decimals_registry,
        clock,
    );

    // check if we need to refund debt coin because there might not be enough ctoken to be liquidated
    let total_ctokens = obligation.ctoken_amount_by_coin(type_name::with_defining_ids<CollateralType>());
    if (total_ctokens < seized_ctokens) {
        let expected_repay_amount = float::from_quotient(total_ctokens, seized_ctokens)
            .mul_u64(available_repay_coin.value())
            // repay a bit more
            .ceil();
        let refund = available_repay_coin.value() - expected_repay_amount;

        refund_coins.join(available_repay_coin.split(refund, ctx));
        seized_ctokens = total_ctokens;

